// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up the depositor account
        address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;
        vm.prank(depositor);
        c.setL1BlockValues(
            1,           // _number
            2,           // _timestamp
            100,         // _basefee
            bytes32(uint256(1)),  // _hash
            3,           // _sequenceNumber
            bytes32(uint256(2)),  // _batcherHash
            200,         // _l1FeeOverhead
            300          // _l1FeeScalar
        );
        // After the call, a specific observable state: number should be 1
        assertTrue(c.number() == 1);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up the depositor account as the caller
        address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;
        vm.prank(depositor);

        // Call setL1BlockValues with arbitrary concrete values
        bool ok;
        try c.setL1BlockValues(1, 2, 3, bytes32(uint256(4)), 5, bytes32(uint256(6)), 7, 8) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference passes (ok = true), buggy reverts (ok = false)
        assertTrue(ok);
    }
}

